import {brushes,settings,strokeMarkup,previewPoints} from './drawing.js';
export const palette=[['Ink','#292536'],['Slate','#68738a'],['White','#ffffff'],['Red','#e34a59'],['Orange','#ec8b35'],['Green','#259b73'],['Blue','#3278e4'],['Purple','#794de8']];
export function drawingControls(values,disabled=false){const s=settings(values),off=disabled?'disabled':'';return `<div class="draw-settings"><div class="draw-label">Pencil type</div><div class="brush-grid" role="group" aria-label="Pencil type">${brushes.map(brush=>`<button class="brush-option ${s.brush===brush.id?'chosen':''}" data-brush="${brush.id}" aria-pressed="${s.brush===brush.id}" ${off}><svg viewBox="0 0 216 64" aria-hidden="true">${strokeMarkup(previewPoints,{...s,brush:brush.id,stroke:brush.id==='pencil'?3:brush.id==='fineliner'?2.5:6})}</svg><span>${brush.name}</span><small>${brush.description}</small></button>`).join('')}</div><div class="draw-label">Color</div><div class="color-picker-row"><div class="color-wheel" data-color-wheel role="slider" tabindex="0" aria-label="Brush hue" style="--current:${s.color}"><span></span></div><label class="color-hex"><span>Exact color</span><input data-draw-prop="color" type="color" value="${s.color}" ${off}></label></div><div class="color-palette" role="group" aria-label="Drawing color">${palette.map(([name,color])=>`<button class="color-swatch ${s.color.toLowerCase()===color?'chosen':''}" data-draw-color="${color}" aria-label="${name}" aria-pressed="${s.color.toLowerCase()===color}" title="${name}" style="--swatch:${color}" ${off}></button>`).join('')}</div><div class="draw-range"><label for="draw-width">Width</label><output id="draw-width-value" for="draw-width">${s.stroke} px</output><input id="draw-width" data-draw-prop="stroke" type="range" min="1" max="30" step=".5" value="${s.stroke}" ${off}></div><label class="perfect-stroke"><input data-draw-prop="perfectStroke" type="checkbox" role="switch" ${s.perfectStroke?'checked':''} ${off}><span><b>Perfect stroke</b><small>Infer a clean line, ellipse, or flowing curve from your gesture.</small></span></label><div class="draw-range ${s.perfectStroke?'disabled-range':''}"><label for="draw-smoothing">Smoothing</label><output id="draw-smoothing-value" for="draw-smoothing">${s.perfectStroke?'Replaced':s.smoothing>=100?'Complete':s.smoothing+'%'}</output><input id="draw-smoothing" data-draw-prop="smoothing" type="range" min="0" max="100" step="1" value="${s.smoothing}" ${s.perfectStroke||disabled?'disabled':''}><div class="range-extremes"><span>Raw</span><span>Complete</span></div></div><div class="stroke-preview"><svg id="draw-preview" viewBox="0 0 216 64" aria-label="Current pencil stroke preview">${strokeMarkup(previewPoints,s)}</svg></div><p class="draw-description">Perfect stroke redraws your gesture as clean geometry. Turn it off to restore the original trace. Ink brush responds to stylus pressure, or drawing speed with a mouse.</p></div>`;}
